VIEWPORTS = {"desktop.png": {"width": 1440, "height": 900}, "mobile.png": {"width": 390, "height": 844}}
log = logging.getLogger(__name__)


def _sandbox_unverified(reason, *, pid=None, parent=None, ancestor=None, seccomp=None,
                        filters=None, baseline_filters=None, parent_filters=None):
    """Closed reason and kernel numbers only; never process text or exceptions."""
    log.warning("pagebuilder_firefox_sandbox_unverified reason=%s pid=%s parent=%s ancestor=%s "
                "seccomp=%s filters=%s baseline_filters=%s parent_filters=%s",
                reason, pid, parent, ancestor, seccomp, filters, baseline_filters, parent_filters)
    return False


def browser_env():
    env = {key: value for key, value in os.environ.items() if key in {
        "PATH", "HOME", "TMPDIR", "LANG", "LC_ALL", "PLAYWRIGHT_BROWSERS_PATH", "SYSTEMROOT",
    }}
    # Scope writable paths to the browser; the worker's HOME stays unchanged.
    env.update(HOME="/tmp", TMPDIR="/tmp")
    return env


def firefox_content_sandbox_verified(proc_root=Path("/proc")):
    """Attest every live content descendant has its own kernel seccomp filter.

    The container's inherited filter alone is not Firefox sandbox evidence.
    This follows static QA's content/ancestry check, with filter-count readback.
    """
    current, processes = os.getpid(), {}
    try:
        entries = list(proc_root.iterdir())
    except OSError:
        return _sandbox_unverified("proc_enumeration_unavailable")
    for entry in entries:
        if not entry.name.isdigit():
            continue
        try:
            command = (entry / "cmdline").read_bytes().replace(b"\0", b" ").decode(errors="ignore")
            fields = {line.split(":", 1)[0]: line.split(":", 1)[1].strip()
                      for line in (entry / "status").read_text().splitlines() if ":" in line}
            parent = int(fields["PPid"])
            seccomp, filters = int(fields["Seccomp"]), int(fields["Seccomp_filters"])
            if parent < 0 or seccomp not in {0, 1, 2} or filters < 0:
                raise ValueError("invalid_process_evidence")
        except (OSError, ValueError, KeyError):
            # A process may exit between enumeration and readback. A live
            # opaque entry cannot be assumed outside the browser's ancestry.
            try:
                vanished = not entry.exists()
            except OSError:
                return _sandbox_unverified("process_liveness_unavailable", pid=int(entry.name))
            if not vanished:
                return _sandbox_unverified("live_process_evidence_unavailable", pid=int(entry.name))
            continue
        processes[int(entry.name)] = (parent, seccomp, filters, command, fields.get("Name", ""))
    baseline = processes.get(current)
    if baseline is None or baseline[1] < 0 or baseline[2] < 0:
        return _sandbox_unverified("baseline_evidence_unavailable", pid=current)
    has_content = False
    for pid, (parent, seccomp, filters, command, name) in processes.items():
        args = command.split()
        content = "-contentproc" in args and "firefox" in command
        ancestor = pid
        ancestors = set()
        while ancestor in processes and ancestor != current:
            if ancestor in ancestors:
                return _sandbox_unverified("ancestry_cycle", pid=pid, parent=parent, ancestor=ancestor)
            ancestors.add(ancestor)
            ancestor = processes[ancestor][0]
        if ancestor != current:
            if content and ancestor not in {0, 1}:
                # A missing parent is not proof of foreign scope.
                return _sandbox_unverified("content_ancestry_unproven", pid=pid, parent=parent,
                    ancestor=ancestor, seccomp=seccomp, filters=filters, baseline_filters=baseline[2])
            continue
        if not content:
            continue
        # The trusted fork server does not render content or install its filter.
        if name == "forkserver" and args[-1] == "forkserver":
            continue
        inherited = processes.get(parent)
        if (seccomp != 2 or inherited is None or inherited[1] < 0 or inherited[2] < 0
                or filters <= max(baseline[2], inherited[2])):
            return _sandbox_unverified("content_filter_unproven", pid=pid, parent=parent, seccomp=seccomp,
                filters=filters, baseline_filters=baseline[2], parent_filters=inherited[2] if inherited else None)
        has_content = has_content or ("-isForBrowser" in args and args[-1] == "tab")
    return has_content or _sandbox_unverified("browser_content_missing", pid=current)


def _launch_browser(pw):
    if sys.platform != "linux":
        return pw.chromium.launch(headless=True, chromium_sandbox=True, env=browser_env(),
                                  **({"channel": "chrome"} if sys.platform == "darwin" else {}))
    if os.geteuid() == 0:
        log.warning("pagebuilder_renderer_step_failed", extra={"step": "non_root", "exception_class": "ValueError"})
        raise ValueError("pagebuilder_renderer_unavailable")
    for attempt in range(2):
        try:
            # Playwright owns an empty-path profile until the browser process
            # exits, including failed launches. Disconnection can precede exit.
            context = pw.firefox.launch_persistent_context(
                "", headless=True, env=browser_env(), timeout=20000,
                accept_downloads=False, service_workers="block",
                firefox_user_prefs={"gfx.webrender.software": True, "media.hardware-video-decoding.enabled": False})
            browser = context.browser
            break
        except Exception as exc:
            log.warning("pagebuilder_renderer_step_failed", extra={
                "step": "launch", "attempt": attempt + 1, "exception_class": type(exc).__name__})
            if attempt == 1:
                raise
            time.sleep(1)
    step = "probe"
    try:
        probe = browser.new_page()
        try:
            probe.goto("data:text/html,<p>Supymem sandbox probe</p>", wait_until="domcontentloaded", timeout=5000)
            step = "sandbox_attest"
            if not firefox_content_sandbox_verified():
                raise ValueError("pagebuilder_renderer_unavailable")
        finally:
            probe.close()
    except Exception as exc:
        log.warning("pagebuilder_renderer_step_failed", extra={"step": step, "exception_class": type(exc).__name__})
        browser.close()
        raise
    log.info("pagebuilder_renderer_step_succeeded", extra={"step": "sandbox_attest"})
    return browser


_SESSION = ContextVar("pagebuilder_browser_session", default=None)


@contextmanager
def renderer_session():
    """One sandboxed browser per job, with a fresh context for every render."""
    if _SESSION.get() is not None:
        yield
        return
    holder = {}
    token = _SESSION.set(holder)
    try:
        yield
    finally:
        try:
            if holder.get("browser") is not None:
                holder["browser"].close()
        finally:
            try:
                if holder.get("driver") is not None:
                    holder["driver"].stop()
            finally:
                _SESSION.reset(token)


@contextmanager
def _browser():
    from playwright.sync_api import sync_playwright
    holder = _SESSION.get()
    if holder is None:
        with sync_playwright() as pw:
            browser = _launch_browser(pw)
            try:
                yield browser
            finally:
                browser.close()
    else:
        if "browser" not in holder:
            holder["driver"] = sync_playwright().start()
            holder["browser"] = _launch_browser(holder["driver"])
        yield holder["browser"]


def require_renderer():
    """Verify the worker's real sandboxed browser before any model call."""
    step = "browser_launch"
    try:
        with _browser() as browser:
            step = "version"
            if not browser.version:
                raise ValueError("pagebuilder_renderer_unavailable")
    except Exception as exc:
        log.warning("pagebuilder_renderer_unavailable", extra={"step": step, "exception_class": type(exc).__name__})
        raise ValueError("pagebuilder_renderer_unavailable") from exc


class _Handler(LoopbackRequest, SimpleHTTPRequestHandler):
    def log_message(self, *_args):
        pass


def prime_images(page):
    """Exercise real lazy loading without changing source attributes."""
    images = page.locator("img")
    if images.count() > 8:
        return ["image_count_budget"]
    failures = []
    for index in range(images.count()):
        try:
            image = images.nth(index)
            image.scroll_into_view_if_needed(timeout=2000)
            page.wait_for_function("el=>el.complete&&el.naturalWidth>0", arg=image.element_handle(), timeout=5000)
            image.evaluate("el=>Promise.race([el.decode(),new Promise((_,reject)=>setTimeout(()=>reject(new Error('decode_timeout')),2000))])")
        except Exception:
            failures.append("image_load")
    page.evaluate("window.scrollTo({top:0,left:0,behavior:'instant'})")
    page.wait_for_timeout(100)
    return failures


def _link_actions(page, origin):
    """Native pointer and sequential Tab/Enter behavior, with remote escape blocked."""
    actions = []
    links = page.locator("a[href]")
    if links.count() > 12:
        return [{"id": "link_limit", "mode": "all", "passed": False, "error": "too_many_links"}]
    count = links.count()
    for index in range(count):
        for mode in ("pointer", "keyboard"):
            page.goto(origin + "/index.html", wait_until="domcontentloaded", timeout=5000)
            link = page.locator("a[href]").nth(index)
            identity = (link.get_attribute("id") or "link_" + str(index))[:40]
            target = link.get_attribute("href") or ""
            try:
                if not link.is_visible() or not link.is_enabled():
                    raise ValueError("hidden_or_disabled")
                # mailto is a contract-approved external link (the signup fallback for a private page with no publishing account).
                remote = target.startswith(("https://", "mailto:"))
                if remote or target.startswith("http://"):
                    from core.static_qa_contracts import Action
                    try:
                        Action(id=identity, kind="external_link", role="link", name=identity, target=target)
                    except ValueError:
                        raise ValueError("unsupported_target") from None
                    remote = True
                if remote:
                    link.evaluate("el => el.addEventListener('click', event => {event.preventDefault();window.__pagebuilderActivated=true}, {capture:true})")
                if mode == "pointer":
                    link.click(timeout=2500)
                else:
                    for _ in range(80):
                        page.keyboard.press("Tab")
                        if link.evaluate("el=>document.activeElement===el"):
                            break
                    else:
                        raise ValueError("keyboard_unreachable")
                    page.keyboard.press("Enter")
                if remote:
                    if not page.evaluate("window.__pagebuilderActivated===true"):
                        raise ValueError("activation_missing")
                elif target.startswith("#") and len(target) > 1:
                    page.wait_for_function("""id=>{const e=document.getElementById(id);if(!e||location.hash!=='#'+id)return false;const r=e.getBoundingClientRect();return r.width>0&&r.height>0&&r.top<innerHeight&&r.bottom>0}""", arg=target[1:], timeout=2000)
                elif re.fullmatch(r"variant_[a-z][a-z0-9_]{0,19}\.html", target):
                    page.wait_for_url(origin + "/" + target, timeout=2000)
                else:
                    raise ValueError("unsupported_target")
                actions.append({"id": identity, "mode": mode, "passed": True})
            except Exception as exc:
                actions.append({"id": identity, "mode": mode, "passed": False,
                                "error": str(exc) if isinstance(exc, ValueError) else "navigation_failed"})
                import logging
                # Which link failed and why, without page content: needed to explain a failed build to the owner.
                logging.getLogger("company_os.pagebuilder").warning("pagebuilder_action_failed", extra={
                    "action_id": identity, "action_mode": mode, "action_error": actions[-1]["error"],
                    "target_kind": target.split(":", 1)[0][:12] if ":" in target[:12] else ("anchor" if target.startswith("#") else "relative")})
    return actions


def render_page(html: str, files: dict[str, str | bytes]) -> dict:
    """Return real screenshots and fixed observations for the bounded repair loop.

    Geometry, computed styles and browser errors are measured. These observations
    are not a vision model's aesthetic judgment or a Lighthouse certification.
    """
    try:
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise ValueError("pagebuilder_renderer_unavailable") from exc
    failures, screenshots, observations = [], {}, {}
    social_preview = b""
    blocked, errors = [], []
    with TemporaryDirectory(prefix="pagebuilder-render-") as temp:
        directory = Path(temp)
        for name, data in {**files, "index.html": html}.items():
            safe_name(name)
            target = directory / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data.encode() if isinstance(data, str) else data)
        server = ThreadingHTTPServer(("127.0.0.1", 0), partial(_Handler, directory=temp))
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        origin = f"http://127.0.0.1:{server.server_port}"
        try:
            with _browser() as browser:
                for name, viewport in VIEWPORTS.items():
                    context = browser.new_context(viewport=viewport, service_workers="block", accept_downloads=False,
                                                  reduced_motion="reduce")

                    def route(request_route):
                        url = urlsplit(request_route.request.url)
                        if request_route.request.method == "GET" and f"{url.scheme}://{url.netloc}" == origin:
                            request_route.continue_()
                        else:
                            blocked.append("external_request")
                            request_route.abort()

                    context.route("**/*", route)
                    context.route_web_socket("**/*", lambda _socket: blocked.append("websocket"))
                    page = context.new_page()
                    context.on("page", lambda popup: (blocked.append("popup"), popup.close()))
                    page.on("pageerror", lambda _error: errors.append("page_exception"))
                    page.on("console", lambda msg: errors.append("console_error") if msg.type == "error" else None)
                    page.on("response", lambda response: errors.append("http_failure") if response.status >= 400 else None)
                    response = page.goto(origin + "/index.html", wait_until="networkidle", timeout=15000)
                    initial_hero_cta = page.evaluate("""() => {
                        const e=document.getElementById('hero_cta');if(!e)return null;
                        const b=e.getBoundingClientRect(),x=(b.left+b.right)/2,y=(b.top+b.bottom)/2;
                        const dx=Math.min(4,b.width/4),dy=Math.min(4,b.height/4);
                        const hitCoverage=[[x,y],[b.left+dx,y],[b.right-dx,y],[x,b.top+dy],[x,b.bottom-dy]]
                            .every(([x,y])=>{const hit=document.elementFromPoint(x,y);return hit===e||e.contains(hit)});
                        return {visible:e.checkVisibility({checkOpacity:true,checkVisibilityCSS:true}),hitCoverage,
                            top:b.top,left:b.left,right:b.right,bottom:b.bottom,width:b.width,height:b.height,
                            withinViewport:b.width>0&&b.height>0&&b.top>=0&&b.left>=0&&b.right<=innerWidth&&b.bottom<=innerHeight};
                    }""")
                    if sys.platform == "linux" and not firefox_content_sandbox_verified():
                        raise ValueError("pagebuilder_renderer_unavailable")
                    image_failures = prime_images(page)
                    failures.extend("render_" + failure + ":" + name.removesuffix(".png") for failure in image_failures)
                    observed = page.evaluate(r"""() => {
                        const visible = e => {
                            const b=e.getBoundingClientRect();
                            if(b.width<=0||b.height<=0||b.right<=0||b.left>=innerWidth)return false;
                            for(let n=e;n;n=n.parentElement){const s=getComputedStyle(n);if(s.display==='none'||s.visibility!=='visible'||Number(s.opacity)<=.01||s.clip!=='auto'||s.clipPath!=='none')return false}
                            return true;
                        };
                        const visibleText = (element,accessible=false) => {
                            const walker=document.createTreeWalker(element,NodeFilter.SHOW_TEXT),parts=[];let node;
                            while(node=walker.nextNode())if(node.textContent.trim()&&visible(node.parentElement)&&!node.parentElement.closest('script,style,template')&&(!accessible||!node.parentElement.closest('[aria-hidden=true]')))parts.push(node.textContent);
                            return parts.join(' ').replace(/\s+/g,' ').trim();
                        };
                        const h1=document.querySelector('h1'), hs=h1&&getComputedStyle(h1), hb=h1&&h1.getBoundingClientRect();
                        const controls=Array.from(document.querySelectorAll('button,a[href],input:not([type=hidden])')).filter(visible);
                        const smallTouchTargets=controls.filter(e=>{const b=e.getBoundingClientRect();return b.width<24||b.height<24}).map(e=>{const b=e.getBoundingClientRect();return {id:e.id,tag:e.tagName.toLowerCase(),width:Math.round(b.width*100)/100,height:Math.round(b.height*100)/100}});
                        const images=Array.from(document.images);
                        const imageClippingFailures=[];
                        for(const image of images.filter(visible)){
                            const b=image.getBoundingClientRect(),style=getComputedStyle(image);
                            const width=image.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),height=image.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);
                            if(style.objectFit==='cover'&&image.naturalHeight&&Math.abs(width-height*image.naturalWidth/image.naturalHeight)>1)
                                imageClippingFailures.push({id:image.id,reason:'object_fit_cover',width,height,naturalWidth:image.naturalWidth,naturalHeight:image.naturalHeight});
                            for(let n=image.parentElement;n&&n!==document.body&&n!==document.documentElement;n=n.parentElement){
                                const s=getComputedStyle(n),r=n.getBoundingClientRect(),left=r.left+n.clientLeft,top=r.top+n.clientTop;
                                if(['inline','contents'].includes(s.display))continue;
                                let transform='none';if([s.overflowX,s.overflowY].some(v=>['hidden','clip','auto','scroll'].includes(v)))
                                    for(let a=n;a;a=a.parentElement)if(getComputedStyle(a).transform!=='none'){transform=getComputedStyle(a).transform;break}
                                if(transform!=='none'){
                                    imageClippingFailures.push({id:image.id,reason:'transformed_clip_ancestor',ancestor:{tag:n.tagName.toLowerCase(),id:n.id,className:n.className},transform});break}
                                const clipX=['hidden','clip','auto','scroll'].includes(s.overflowX)&&(b.left<left-1||b.right>left+n.clientWidth+1);
                                const clipY=['hidden','clip','auto','scroll'].includes(s.overflowY)&&(b.top<top-1||b.bottom>top+n.clientHeight+1);
                                if(clipX||clipY){imageClippingFailures.push({id:image.id,ancestor:{tag:n.tagName.toLowerCase(),id:n.id,className:n.className},clipX,clipY});break}
                            }
                        }
                        const boxes=Array.from(document.querySelectorAll('main section,main>div')).filter(visible).map(e=>{const b=e.getBoundingClientRect(),s=getComputedStyle(e);return {height:Math.round(b.height),paddingTop:s.paddingTop,paddingBottom:s.paddingBottom}});
                        const rgba = value => {const numbers=value.match(/[\d.]+/g);return numbers&&numbers.length>=3?[+numbers[0],+numbers[1],+numbers[2],numbers[3]===undefined?1:+numbers[3]]:null};
                        const blend = (color,background) => color.slice(0,3).map((v,i)=>v*color[3]+background[i]*(1-color[3]));
                        const lum = color => color.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((sum,v,i)=>sum+v*[.2126,.7152,.0722][i],0);
                        const contrastFailures=[],contrastUnresolved=[];let contrastChecked=0,contrastSkipped=0;
                        for(const e of Array.from(document.body.querySelectorAll('*')).slice(0,500)) {
                            if(!visible(e)||!Array.from(e.childNodes).some(n=>n.nodeType===3&&n.textContent.trim()))continue;
                            const style=getComputedStyle(e),color=rgba(style.color),layers=[];let backgroundImage=null,opacity=null,visualEffect=null;
                            for(let node=e;node;node=node.parentElement){const s=getComputedStyle(node),bg=rgba(s.backgroundColor);if(s.backgroundImage!=='none')backgroundImage={tag:node.tagName.toLowerCase(),id:node.id,className:node.className,value:s.backgroundImage.slice(0,300)};if(bg&&bg[3])layers.push(bg);if(bg&&bg[3]===1)break}
                            for(let node=e;node;node=node.parentElement){const s=getComputedStyle(node);
                                if(!opacity&&Number(s.opacity)!==1)opacity={tag:node.tagName.toLowerCase(),id:node.id,value:s.opacity};
                                if(!visualEffect&&(s.filter!=='none'||s.backdropFilter!=='none'||s.mixBlendMode!=='normal'))visualEffect={tag:node.tagName.toLowerCase(),id:node.id,filter:s.filter,backdropFilter:s.backdropFilter,mixBlendMode:s.mixBlendMode};}
                            if(backgroundImage||opacity||visualEffect||!color||color[3]===0){contrastSkipped++;contrastUnresolved.push({tag:e.tagName.toLowerCase(),id:e.id,className:e.className,text:e.innerText?.trim().replace(/\s+/g,' ').slice(0,120),reason:backgroundImage?'background_image':opacity?'group_opacity':visualEffect?'visual_effect':'foreground_unavailable',backgroundImage,opacity,visualEffect});continue}
                            let background=[255,255,255];for(const layer of layers.reverse())background=blend(layer,background);
                            const values=[lum(blend(color,background)),lum(background)].sort((a,b)=>a-b),ratio=(values[1]+.05)/(values[0]+.05);
                            const size=parseFloat(style.fontSize),large=size>=24||(size>=18.66&&parseInt(style.fontWeight)>=700),minimum=large?3:4.5;
                            contrastChecked++;if(ratio+.05<minimum)contrastFailures.push({tag:e.tagName.toLowerCase(),id:e.id,className:typeof e.className==='string'?e.className:'',text:e.innerText?.trim().replace(/\s+/g,' ').slice(0,120),foreground:style.color,background:background.map(Math.round),fontSize:style.fontSize,ratio:Math.round(ratio*100)/100,minimum});
                        }
                        return {
                            overflow:document.documentElement.scrollWidth>innerWidth+2,
                            headingVisible:!!(h1&&visible(h1)), headingCount:document.querySelectorAll('h1').length,
                            headingFont:hs?.fontFamily,bodyFont:getComputedStyle(document.body).fontFamily,
                            headingSize:hs?parseFloat(hs.fontSize):0,headingLineHeight:hs?.lineHeight,
                            headingTop:hb?Math.round(hb.top):null,headingWidth:hb?Math.round(hb.width):0,
                            bodySize:parseFloat(getComputedStyle(document.body).fontSize),
                            brokenImages:images.filter(i=>!i.complete||!i.naturalWidth).length,
                            missingAlt:images.filter(i=>!i.getAttribute('alt')?.trim()).length,
                            visibleImages:images.filter(visible).map(i=>{const b=i.getBoundingClientRect();return {id:i.id,width:Math.round(b.width),height:Math.round(b.height),alt:i.alt}}),
                            imageClippingFailures:imageClippingFailures.slice(0,12),
                            smallTouchTargets:smallTouchTargets.length,smallTouchTargetFailures:smallTouchTargets.slice(0,12),
                            mainLandmark:document.querySelectorAll('main').length===1,
                            blankFooters:Array.from(document.querySelectorAll('footer')).filter(e=>visible(e)&&!e.innerText.trim()&&!e.querySelector('img,svg,a,button,input')).length,
                            brokenAnchors:Array.from(document.querySelectorAll('a[href^="#"]')).filter(a=>a.hash.length>1&&!document.getElementById(a.hash.slice(1))).length,
                            sectionSpacing:boxes.slice(0,12),textLength:document.body.innerText.trim().length,
                            contrastChecked,contrastSkipped,contrastFailures:contrastFailures.slice(0,12),contrastUnresolved:contrastUnresolved.slice(0,12),
                            pageHeight:document.documentElement.scrollHeight,
                            visibleText:visibleText(document.body).slice(0,24000),
                            visibleControls:controls.slice(0,50).map(e=>({
                                id:e.id,role:e.getAttribute('role')||(e.tagName==='A'?'link':'button'),
                                name:(e.getAttribute('aria-label')||(e.getAttribute('aria-labelledby')||'').split(/\s+/).map(id=>document.getElementById(id)?.textContent||'').join(' ').trim()||visibleText(e,true)||e.value||'').trim(),
                                target:e.getAttribute('href')||'',enabled:!e.disabled&&e.getAttribute('aria-disabled')!=='true'
                            }))
                        };
                    }""")
                    observed["initialHeroCta"] = initial_hero_cta
                    label = name.removesuffix(".png")
                    conditions = {
                        "http": bool(response and response.status == 200),
                        "overflow": not observed["overflow"],
                        "heading": observed["headingVisible"] and observed["headingCount"] == 1,
                        "images": observed["brokenImages"] == 0 and observed["missingAlt"] == 0,
                        "image_scale": len([image for image in observed["visibleImages"] if image["width"] >= 160 and image["height"] >= 90]) >= 2,
                        "image_clipping": not observed["imageClippingFailures"],
                        "hero_cta_initial": bool(initial_hero_cta and initial_hero_cta["visible"] and initial_hero_cta["withinViewport"] and initial_hero_cta["hitCoverage"]),
                        "touch_targets": observed["smallTouchTargets"] == 0,
                        "main": observed["mainLandmark"],
                        "anchors": observed["brokenAnchors"] == 0,
                        "footer": observed["blankFooters"] == 0,
                        "hierarchy": observed["headingSize"] >= 28 and observed["bodySize"] >= 14,
                        "text": observed["textLength"] > 80,
                        "contrast": not observed["contrastFailures"] and observed["contrastChecked"] > 0 and observed["contrastSkipped"] == 0,
                        "page_height": observed["pageHeight"] <= 20000,
                    }
                    failures.extend("render_" + key + ":" + label for key, passed in conditions.items() if not passed)
                    screenshots[name] = page.screenshot(type="png", full_page=observed["pageHeight"] <= 20000,
                                                       animations="disabled", timeout=5000)
                    actions = _link_actions(page, origin)
                    failures.extend("render_action:" + action["id"] + ":" + action["mode"] + ":" + label for action in actions if not action["passed"])
                    observed["actions"] = actions
                    observations[label] = {**observed, "checks": conditions, "viewport": viewport}
                    if label == "desktop":
                        page.set_viewport_size({"width": 1200, "height": 630})
                        page.goto(origin + "/index.html", wait_until="networkidle", timeout=15000)
                        social_preview = page.screenshot(type="png", full_page=False,
                                                         animations="disabled", timeout=5000)
                    context.close()
                version = browser.version
        except Exception as exc:
            raise ValueError("pagebuilder_render_failed") from exc
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=2)
    if blocked:
        failures.append("render_external_request")
    if errors:
        failures.append("render_browser_error")
    if sum(len(image) for image in screenshots.values()) + len(social_preview) > 10 * 1024 * 1024:
        failures.append("render_evidence_size_budget")
    return {"passed": not failures, "failures": sorted(set(failures)), "screenshots": screenshots,
            "observations": observations, "browser_rendered": True, "browser_version": version,
            "browser_engine": "firefox" if sys.platform == "linux" else "chromium",
            "browser_sandbox_verified": sys.platform == "linux",
            "critique_method": "deterministic_browser_observations", "vision_critique": False,
            "lighthouse_measured": False, "blocked_requests": len(blocked), "browser_errors": len(errors),
            "social_preview_png": social_preview}
